Self-Service Web/Mobile Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(self_service_web_mobile_portal, "Self-Service Web/Mobile Portal") {
    Component(Web_and_Mobile_Frontend_Assets, "Web and Mobile Frontend Assets", "EU-hosted CDN, HTML/JS, Subresource Integrity (SRI), Content Security Policy (CSP)", "Serves patrons and librarians with secure access, robust accessibility, and geo-pinned EU data residency.")
    Component(Authentication_Manager, "Authentication Manager", "OAuth2/OIDC with PKCE, HTTP-only Secure SameSite=Strict cookies, Secure Enclaves", "Handles secure authentication, token management, and session security.")
    Component(Observability_and_RUM_Agent, "Observability and RUM Agent", "Real User Monitoring (RUM)", "Tracks latency to meet the <800ms non-functional requirement.")
}

Rel(Web_and_Mobile_Frontend_Assets, Authentication_Manager, "Authenticates users via", "OAuth2/OIDC, PKCE, HTTP-only cookies")
Rel(Web_and_Mobile_Frontend_Assets, Observability_and_RUM_Agent, "Reports performance metrics for", "<800ms NFR tracking")

@enduml

API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(Edge_Security_and_Token_Validator, "Edge Security and Token Validator", "OAuth2/OIDC & JWT", "Performs edge token validation, scope enforcement, and role-based access control.")
    Component(Traffic_Router_and_mTLS_Manager, "Traffic Router and mTLS Manager", "Kubernetes & cert-manager", "Secures, routes, and manages ingress/egress traffic with automated mTLS certificate handling.")
}

Rel(Edge_Security_and_Token_Validator, Traffic_Router_and_mTLS_Manager, "Passes authenticated and authorized requests for secure routing")

@enduml

Core Circulation and Transactional Datab.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Core Circulation and Transactional Database container

Container_Boundary(core_circulation_db, "Core Circulation and Transactional Database") {
    Component(Transaction_Manager, "Transaction Manager", "PostgreSQL with Raft/Patroni", "Handles core circulation transactions and ensures strong consistency.")
    Component(Change_Data_Capture_Publisher, "Change Data Capture Publisher", "Debezium", "Reads from the database write-ahead log (WAL) to publish domain events.")
}

Rel(Transaction_Manager, Change_Data_Capture_Publisher, "Publishes domain events via Write-Ahead Log", "Debezium, WAL, JWE")

@enduml

Read-optimized Search Index.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Read-optimized Search Index container

Container_Boundary(search_index, "Read-optimized Search Index") {
    Component(search_query_processor, "Search Query Processor", "Elasticsearch, Query-time JWT filtering", "Processes incoming search requests from the API Gateway and enforces security filtering.")
    Component(data_sync_consumer, "Data Synchronization Consumer", "Debezium, Elasticsearch Sink", "Receives real-time database updates via Change Data Capture to maintain search index consistency.")
}

Rel(search_query_processor, data_sync_consumer, "Accesses synchronized indices for discovery", "TLS 1.3")

@enduml

Admin/Reporting Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Admin/Reporting Container", "Admin/Reporting Container") {
    Component("Administrative Workload Handler", "Administrative Workload Handler", "Kubernetes Container", "Handles administrative workloads and enforces strict EU data residency.")
    Component("Financial Auditing Engine", "Financial Auditing Engine", "Kubernetes Container", "Manages financial auditing processes and compliance data export.")
    Component("Data Analytics Processor", "Data Analytics Processor", "Asynchronous Workers / Elasticsearch", "Performs data analytics and manages read-optimized search index queries.")
}

Rel("Administrative Workload Handler", "Financial Auditing Engine", "Coordinates administrative data with financial audit logs")
Rel("Financial Auditing Engine", "Data Analytics Processor", "Feeds audited data to analytics and reporting pipelines")

@enduml
